"""Local-only Cycles worker. Paths are generated by the trusted local server."""
import json, sys, math, time, pathlib
ROOT = pathlib.Path(__file__).resolve().parents[2]
sys.path.insert(0, str(ROOT / '.local' / 'python'))
import jsonschema
import bpy
from mathutils import Vector, Quaternion

def linear(v):
    return v / 12.92 if v <= 0.04045 else ((v + 0.055) / 1.055) ** 2.4

def position(v, scale=0.1):
    return Vector((v[0]*scale, -v[2]*scale, v[1]*scale))

def aim(obj, source):
    direction = position(source['target']) - position(source['position'])
    up = position(source['up'], 1).normalized()
    z = -direction.normalized()
    x = up.cross(z).normalized()
    y = z.cross(x).normalized()
    from mathutils import Matrix
    obj.rotation_euler = Matrix((x,y,z)).transposed().to_euler()

def main():
    started=time.time()
    job_dir=pathlib.Path(sys.argv[sys.argv.index('--')+1]).resolve()
    payload=json.loads((job_dir/'input.json').read_text(encoding='utf-8'))
    scene_data=payload['scene']
    schema=json.loads((ROOT/'packages/contracts/scene.schema.json').read_text(encoding='utf-8'))
    jsonschema.validate(scene_data,schema)
    geometry=json.loads((job_dir/'mesh.json').read_text(encoding='utf-8'))
    bpy.ops.wm.read_factory_settings(use_empty=True)
    scene=bpy.context.scene
    scene.render.engine='CYCLES'
    prefs=bpy.context.preferences.addons['cycles'].preferences
    device_name='CPU'
    for backend in ['OPTIX','CUDA','HIP','ONEAPI','METAL']:
        try:
            prefs.compute_device_type=backend
            prefs.get_devices()
            devices=[d for d in prefs.devices if d.type==backend]
            if devices:
                for d in prefs.devices: d.use=d.type==backend
                scene.cycles.device='GPU'
                device_name=','.join(d.name for d in devices)
                break
        except (TypeError,RuntimeError): pass
    scene.cycles.samples=64 if payload['purpose']=='preview' else 256
    scene.cycles.use_adaptive_sampling=True
    scene.cycles.adaptive_threshold=0.03 if payload['purpose']=='preview' else 0.01
    scene.cycles.use_denoising=True
    scene.cycles.denoiser='OPENIMAGEDENOISE'
    scene.cycles.max_bounces=12
    scene.cycles.transmission_bounces=8
    scene.cycles.transparent_max_bounces=8
    scene.cycles.diffuse_bounces=4
    scene.cycles.glossy_bounces=4
    scene.cycles.caustics_reflective=False
    scene.cycles.caustics_refractive=False
    scene.cycles.sample_clamp_direct=0
    scene.cycles.sample_clamp_indirect=0
    scene.cycles.seed=42
    scene.render.resolution_x=payload['width']
    scene.render.resolution_y=payload['height']
    scene.render.resolution_percentage=100
    scene.render.film_transparent=payload['transparent']
    scene.view_settings.view_transform='Standard'
    scene.view_settings.look='None'
    scene.view_settings.exposure=scene_data['colorManagement']['exposureEV']
    scene.view_settings.gamma=1
    scene.render.image_settings.file_format='PNG' if payload['format']=='png' else 'JPEG'
    scene.render.image_settings.color_mode='RGBA' if payload['format']=='png' else 'RGB'
    scene.render.image_settings.color_depth='8'
    scene.render.image_settings.quality=95
    scene.render.filepath=str(job_dir/('result.'+payload['format']))
    enhanced_bloom=scene_data.get('postprocessing',{}).get('enhancedBloom',False)
    scene.use_nodes=bool(scene_data['volumetrics']['enabled'] or enhanced_bloom)
    if scene.use_nodes:
        compositor=scene.node_tree;compositor.nodes.clear()
        render_layers=compositor.nodes.new('CompositorNodeRLayers')
        glare=compositor.nodes.new('CompositorNodeGlare');glare.glare_type='FOG_GLOW';glare.quality='HIGH';glare.threshold=0.75;glare.size=6;glare.mix=-0.4 if enhanced_bloom else -0.82
        composite=compositor.nodes.new('CompositorNodeComposite')
        compositor.links.new(render_layers.outputs['Image'],glare.inputs['Image']);compositor.links.new(glare.outputs['Image'],composite.inputs['Image'])
    scene.world=bpy.data.worlds.new('Environment')
    scene.world.use_nodes=True
    nodes=scene.world.node_tree.nodes; links=scene.world.node_tree.links
    nodes.clear()
    out=nodes.new('ShaderNodeOutputWorld')
    black=nodes.new('ShaderNodeBackground');black.inputs['Color'].default_value=(0,0,0,1)
    bg=nodes.new('ShaderNodeBackground')
    base=scene_data['background']['color']['value']
    bottom=tuple(linear(v*0.34)/(2**scene.view_settings.exposure) for v in base)+(1,)
    top_rgb=[min(1.0,v+(0.08 if i==2 else 0.035)) for i,v in enumerate(base)]
    top=tuple(linear(v)/(2**scene.view_settings.exposure) for v in top_rgb)+(1,)
    tex=nodes.new('ShaderNodeTexCoord');separate=nodes.new('ShaderNodeSeparateXYZ');ramp=nodes.new('ShaderNodeValToRGB')
    ramp.color_ramp.elements[0].position=0.22;ramp.color_ramp.elements[0].color=bottom
    ramp.color_ramp.elements[1].position=0.86;ramp.color_ramp.elements[1].color=top
    links.new(tex.outputs['Normal'],separate.inputs['Vector']);links.new(separate.outputs['Z'],ramp.inputs['Fac']);links.new(ramp.outputs['Color'],bg.inputs['Color'])
    rays=nodes.new('ShaderNodeLightPath')
    either=nodes.new('ShaderNodeMath');either.operation='MAXIMUM'
    links.new(rays.outputs['Is Camera Ray'],either.inputs[0])
    links.new(rays.outputs['Is Transmission Ray'],either.inputs[1])
    mix=nodes.new('ShaderNodeMixShader');links.new(either.outputs[0],mix.inputs[0]);links.new(black.outputs[0],mix.inputs[1]);links.new(bg.outputs[0],mix.inputs[2]);links.new(mix.outputs[0],out.inputs[0])
    materials={}
    for data in scene_data['materials']:
        mat=bpy.data.materials.new(data['id']);mat.use_nodes=True
        n=mat.node_tree.nodes;link=mat.node_tree.links
        principled=n.get('Principled BSDF')
        principled.inputs['Base Color'].default_value=tuple(linear(v) for v in data['baseColor']['value'])+(1,)
        principled.inputs['Metallic'].default_value=data['metalness']
        principled.inputs['Roughness'].default_value=data['roughness']
        principled.inputs['Transmission Weight'].default_value=data['transmission']
        principled.inputs['IOR'].default_value=data['ior']
        if 'Emission Color' in principled.inputs:
            principled.inputs['Emission Color'].default_value=tuple(linear(v) for v in data['emissiveColor']['value'])+(1,)
        if 'Emission Strength' in principled.inputs:
            principled.inputs['Emission Strength'].default_value=data['emissiveIntensity']
        if 'Coat Weight' in principled.inputs:
            principled.inputs['Coat Weight'].default_value=data['clearcoat']
            principled.inputs['Coat Roughness'].default_value=data['clearcoatRoughness']
        if data['preset'] in ('glass','amber-glass','crystal'):
            volume=n.new('ShaderNodeVolumeAbsorption')
            sigma=data['absorptionPerMeter']; density=max(max(sigma),1e-10)
            # Cycles absorption closure computes (1 - color) * density.
            volume.inputs['Color'].default_value=tuple(1-v/density for v in sigma)+(1,)
            volume.inputs['Density'].default_value=density
            link.new(volume.outputs[0],n.get('Material Output').inputs['Volume'])
        materials[data['id']]=mat
    if scene_data['volumetrics']['enabled']:
        medium=bpy.data.materials.new('VolumetricMedium');medium.use_nodes=True
        medium_nodes=medium.node_tree.nodes;medium_links=medium.node_tree.links;medium_nodes.clear()
        medium_output=medium_nodes.new('ShaderNodeOutputMaterial');medium_volume=medium_nodes.new('ShaderNodeVolumePrincipled')
        medium_volume.inputs['Density'].default_value=scene_data['volumetrics']['density']*scene_data['volumetrics']['intensity']
        medium_volume.inputs['Anisotropy'].default_value=scene_data['volumetrics']['anisotropy']
        medium_links.new(medium_volume.outputs['Volume'],medium_output.inputs['Volume'])
        medium_mesh=bpy.data.meshes.new('VolumetricBounds');medium_mesh.from_pydata([(-0.75,-0.75,-0.75),(0.75,-0.75,-0.75),(0.75,0.75,-0.75),(-0.75,0.75,-0.75),(-0.75,-0.75,0.75),(0.75,-0.75,0.75),(0.75,0.75,0.75),(-0.75,0.75,0.75)],[],[(0,1,2),(0,2,3),(4,6,5),(4,7,6),(0,4,5),(0,5,1),(1,5,6),(1,6,2),(2,6,7),(2,7,3),(4,0,3),(4,3,7)]);medium_mesh.update()
        medium_object=bpy.data.objects.new('VolumetricBounds',medium_mesh);scene.collection.objects.link(medium_object);medium_object.data.materials.append(medium)
    transform=scene_data['objects'][0]['transform']
    basis=Quaternion((1,0,0),math.pi/2)
    q=transform['rotation'];rotation=basis @ Quaternion((q[3],q[0],q[1],q[2])) @ basis.inverted()
    for part in geometry['parts']:
        mesh=bpy.data.meshes.new(part['id'])
        verts=[position(part['positions'][i:i+3]) for i in range(0,len(part['positions']),3)]
        faces=[part['indices'][i:i+3] for i in range(0,len(part['indices']),3)]
        mesh.from_pydata(verts,[],faces);mesh.update()
        for polygon in mesh.polygons:polygon.use_smooth=True
        normals=[position(part['normals'][i:i+3],1) for i in range(0,len(part['normals']),3)]
        mesh.normals_split_custom_set_from_vertices(normals)
        uv=mesh.uv_layers.new(name='UV0')
        for loop in mesh.loops:uv.data[loop.index].uv=part['uvs'][loop.vertex_index*2:loop.vertex_index*2+2]
        obj=bpy.data.objects.new(part['id'],mesh);scene.collection.objects.link(obj)
        obj.location=position(transform['position']);obj.rotation_mode='QUATERNION';obj.rotation_quaternion=rotation;obj.scale=(transform['scale'],)*3
        obj.data.materials.append(materials[scene_data['objects'][0]['partMaterialAssignments'][part['id']]])
    for data in scene_data['lights']:
        lamp=bpy.data.lights.new(data['id'],'AREA');lamp.shape='RECTANGLE';lamp.size=data['width']*.1;lamp.size_y=data['height']*.1;lamp.energy=data['powerWatts'];lamp.color=tuple(linear(v) for v in data['color']['value'])
        obj=bpy.data.objects.new(data['id'],lamp);scene.collection.objects.link(obj);obj.location=position(data['position']);aim(obj,data)
    data=scene_data['camera'];cam=bpy.data.cameras.new('Camera');cam.sensor_fit='VERTICAL';cam.sensor_height=24;cam.lens=12/math.tan(data['verticalFovRad']/2);cam.clip_start=data['near']*.1;cam.clip_end=data['far']*.1
    obj=bpy.data.objects.new('Camera',cam);scene.collection.objects.link(obj);obj.location=position(data['position']);aim(obj,data);scene.camera=obj
    print('FORM_DEVICE '+device_name,flush=True)
    bpy.ops.render.render(write_still=True)
    (job_dir/'metrics.json').write_text(json.dumps({'seconds':round(time.time()-started,2),'device':device_name,'blender':bpy.app.version_string,'width':payload['width'],'height':payload['height'],'samples':scene.cycles.samples}),encoding='utf-8')

if __name__=='__main__': main()
